// Mensajes de error que llegan en castellano desde módulos sin acceso al
// idioma (cuentas locales). Se traducen acá para no duplicar la lógica.
const ERROR_MESSAGES_GN = {
  'Escribí un número de teléfono válido (al menos 7 dígitos).': 'Ehai peteĩ número de teléfono oĩ porãva (7 dígito michĩvéramo).',
  'Escribí un correo válido, por ejemplo nombre@ejemplo.com.': 'Ehai peteĩ correo oĩ porãva, techapyrã nombre@ejemplo.com.',
  'La foto no es válida o es demasiado grande.': 'Ko ta’anga ndoikói térã tuichaiterei.',
  'Escribí tu nombre.': 'Ehai nde réra.',
  'El usuario debe tener entre 3 y 24 letras, números, puntos, guiones o guiones bajos.': 'Nde usuario oguerekova’erã 3 guive 24 peve letra, número, punto térã guion.',
  'La contraseña debe tener al menos 8 caracteres.': 'Contraseña oguerekova’erã 8 caracter michĩvéramo.',
  'Elegí Alumno o Maestro.': 'Eiporavo Temimbo’e térã Mbo’ehára.',
  'Ese nombre de usuario ya existe en este dispositivo.': 'Ko nombre de usuario oĩma ko dispositivo-pe.',
  'Usuario o contraseña incorrectos.': 'Usuario térã contraseña ndoikói.',
  'No se encontró la cuenta en este dispositivo.': 'Ndojejuhúi pe cuenta ko dispositivo-pe.',
  'Elegí un archivo de imagen (JPG, PNG o WebP).': 'Eiporavo peteĩ ta’anga (JPG, PNG térã WebP).',
  'No se pudo abrir la imagen. Probá con otra.': 'Ndaikatúi ojeike ta’angápe. Eñeha’ã ambuéva reheve.',
  'La imagen es demasiado grande. Probá con otra más simple.': 'Ta’anga tuichaiterei. Eñeha’ã ambuéva reheve.',
};

export function localizeError(language, message) {
  if (language === 'es' || !message) return message;
  return ERROR_MESSAGES_GN[message] ?? message;
}

/** Traduce una clave; `vars` reemplaza los marcadores {nombre}. Si falta en
 * Jopara se usa el español, y si falta en los dos se devuelve la clave (así
 * una clave faltante se nota en pantalla en vez de quedar vacía). */
export function translate(language, key, vars) {
  const text = messages[language]?.[key] ?? messages.es[key] ?? key;
  if (!vars) return text;
  return text.replace(/\{(\w+)\}/g, (match, name) => (vars[name] ?? match));
}

export default messages;
